def normalize_tags(text):
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    seen = set()
    result = []
    for token in text.split(","):
        tag = token.strip().casefold()
        if not tag or tag in seen:
            continue
        seen.add(tag)
        result.append(tag)
    return result

def topological_batches(dependencies):
    """Return deterministic topological batches (maximal ready layers).

    dependencies: dict mapping nonempty str node -> list/tuple of nonempty str
    prerequisite names, each of which must also be a key.
    Raises ValueError on malformed input, missing references, or cycles.
    """
    if type(dependencies) is not dict:
        raise ValueError("dependencies must be a dict")

    prereqs = {}
    for node, deps in dependencies.items():
        if not isinstance(node, str) or not node:
            raise ValueError("node names must be nonempty strings")
        if not isinstance(deps, (list, tuple)):
            raise ValueError("prerequisites must be a list or tuple")
        seen = set()
        for dep in deps:
            if not isinstance(dep, str) or not dep:
                raise ValueError("prerequisite names must be nonempty strings")
            seen.add(dep)
        prereqs[node] = seen

    for node, deps in prereqs.items():
        for dep in deps:
            if dep not in prereqs:
                raise ValueError("missing dependency: %r" % (dep,))
        if node in deps:
            raise ValueError("self dependency: %r" % (node,))

    dependents = {node: [] for node in prereqs}
    indegree = {}
    for node, deps in prereqs.items():
        indegree[node] = len(deps)
        for dep in deps:
            dependents[dep].append(node)

    batches = []
    ready = sorted(node for node, deg in indegree.items() if deg == 0)
    processed = 0
    while ready:
        batches.append(ready)
        processed += len(ready)
        next_ready = []
        for node in ready:
            for child in dependents[node]:
                indegree[child] -= 1
                if indegree[child] == 0:
                    next_ready.append(child)
        ready = sorted(next_ready)

    if processed != len(prereqs):
        raise ValueError("dependency graph contains a cycle")
    return batches

def merge_ranges(ranges):
    if not isinstance(ranges, (list, tuple)):
        raise ValueError("ranges must be a list or tuple")
    items = []
    for item in ranges:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("each range must be a list or tuple of two ints")
        start, end = item
        if type(start) is not int or type(end) is not int:
            raise ValueError("bounds must be ints (bool not allowed)")
        if start > end:
            raise ValueError("start must be <= end")
        items.append((start, end))
    items.sort()
    merged = []
    for start, end in items:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

