def _validate_pair(item, index):
    """Return a fresh (start, end) tuple for one caller-supplied range.

    Raises ValueError for any malformed pair. Never modifies ``item``.
    """
    if not isinstance(item, (list, tuple)):
        raise ValueError(f"range at index {index} must be a list or tuple")
    if len(item) != 2:
        raise ValueError(f"range at index {index} must have exactly two bounds")
    start, end = item[0], item[1]
    if type(start) is not int or type(end) is not int:
        raise ValueError(f"range at index {index} has a non-integer bound")
    if start > end:
        raise ValueError(f"range at index {index} has start greater than end")
    return (start, end)


def merge_ranges(ranges):
    """Merge overlapping closed integer intervals.

    ``ranges`` must be a list or tuple of ``[start, end]`` (or ``(start, end)``)
    pairs with exact int bounds (bool is rejected) and ``start <= end``.

    Intervals that overlap or share an endpoint are merged; adjacent but
    disjoint intervals such as ``[1, 2]`` and ``[3, 4]`` remain separate.

    Returns a new list of ``[start, end]`` lists sorted by start. The caller's
    input is never modified, including when a ValueError is raised.
    """
    if not isinstance(ranges, (list, tuple)):
        raise ValueError("ranges must be a list or tuple")

    # Validate everything first so malformed input fails before any work.
    normalized = [_validate_pair(item, i) for i, item in enumerate(ranges)]

    # Sorting fresh tuples gives a deterministic order (start, then end).
